package com.kennedy.wallet.config;
import com.kennedy.wallet.service.JwtService; import com.kennedy.wallet.repository.UserRepository; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder;
public class JwtAuthFilter extends OncePerRequestFilter {private final JwtService jwt;private final UserRepository users;public JwtAuthFilter(JwtService j,UserRepository u){jwt=j;users=u;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var c=jwt.parse(h.substring(7));if(c.getId()==null||c.getId().isBlank())throw new IllegalArgumentException("Missing token ID");var user=users.findById(java.util.UUID.fromString(c.getSubject())).orElse(null);if(user!=null&&user.isEnabled()&&(user.getLockedUntil()==null||!user.getLockedUntil().isAfter(java.time.Instant.now()))){var auth=new UsernamePasswordAuthenticationToken(user.getId().toString(),null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+user.getRole().name())));SecurityContextHolder.getContext().setAuthentication(auth);}}catch(RuntimeException ignored){SecurityContextHolder.clearContext();}chain.doFilter(req,res);}}
